async function load(){const [s,m,g,sc,rp]=await Promise.all([sb.from('staff').select('*').order('created_at'),sb.from('daily_marks').select('*'),sb.rpc('get_schedule_assignments'),sb.from('schedule_slots').select('*'),sb.from('schedule_replacements').select('*').order('created_at',{ascending:false})]);db.staff=(s.data||[]).map(x=>({id:x.id,name:x.name,role:x.role,appointed:x.appointed_at||'',dismissed:x.dismissed_at||'',yellow:x.yellow_cards,red:x.red_cards}));db.marks={};(m.data||[]).forEach(x=>db.marks[x.staff_id+'|'+x.mark_date]={status:x.status,norm:x.norm_value,note:x.note});db.schedule=g.data||[];db.replacements=rp.data||[];db.slotCaps={};(sc.data||[]).forEach(x=>db.slotCaps[x.slot_key]=x.capacity);let errs=[s,m,g,sc,rp].filter(x=>x.error).map(x=>x.error.message);$('connection').textContent=errs.length?'● Интерфейс загружен · часть данных недоступна':'● Данные синхронизированы';renderAll()}
function metrics(a){let ok=0,bad=0,low=0,missing=0,total=0,norm=0,activeDays=0,today=dk(new Date());for(let d=1;d<=dim();d++){let date=key(month.getFullYear(),month.getMonth(),d);if(date>today||(a.appointed&&date<a.appointed)||(a.dismissed&&date>a.dismissed))continue;const x=mark(a.id,date);if(x.status==='inactive'){bad++;continue}total++;if(x.status==='norm'){activeDays++;norm+=+x.norm||0;if(+x.norm>=required(a))ok++;else low++}else missing++}return{ok,bad,low,missing,total,norm,avg:activeDays?norm/activeDays:0,pct:total?Math.round(ok/total*100):0}}
