function safeRender(fn,name){try{fn()}catch(e){console.error('Render '+name,e)}}function streaks(a){let today=dk(new Date()),cur=0,best=0,miss=0,lowRun=0,maxMiss=0,maxLow=0;for(let d=1;d<=dim();d++){let date=key(month.getFullYear(),month.getMonth(),d);if(date>today||(a.appointed&&date<a.appointed)||(a.dismissed&&date>a.dismissed))continue;let x=mark(a.id,date);if(x.status==='inactive')continue;if(x.status==='norm'&&+x.norm>=required(a)){cur++;best=Math.max(best,cur);miss=0;lowRun=0}else{cur=0;if(x.status==='none'){miss++;maxMiss=Math.max(maxMiss,miss);lowRun=0}else if(x.status==='norm'){lowRun++;maxLow=Math.max(maxLow,lowRun);miss=0}}}return{cur,best,maxMiss,maxLow}}function renderAlerts(){let alerts=[];db.staff.filter(a=>!a.dismissed).forEach(a=>{let m=metrics(a),st=streaks(a);if(st.maxMiss>=2)alerts.push({a,type:'danger',txt:'Пропуски отчёта подряд: '+st.maxMiss,score:10+st.maxMiss});if(st.maxLow>=2)alerts.push({a,type:'warn',txt:'Недобор нормы подряд: '+st.maxLow,score:7+st.maxLow});if(m.total>=3&&m.pct<60)alerts.push({a,type:'warn',txt:'Стабильность за месяц: '+m.pct+'%',score:6});});alerts.sort((a,b)=>b.score-a.score);$('alertsCount').textContent=alerts.length;$('alertsPanel').hidden=!alerts.length;$('alertsList').innerHTML=alerts.slice(0,8).map(v=>'<button class="alertRow '+v.type+'" data-id="'+v.a.id+'"><span class="alertIcon">'+(v.type==='danger'?'!':'↓')+'</span><div><b>'+esc(v.a.name)+'</b><small>'+v.txt+'</small></div><span>Профиль ›</span></button>').join('');document.querySelectorAll('.alertRow').forEach(b=>b.onclick=()=>openHistory(b.dataset.id))}const SLOTS=[{k:'06-08',t:'06:00–08:00',group:'06:00–11:00',cap:2},{k:'08-11',t:'08:00–11:00',group:'06:00–11:00',cap:2},{k:'11-13',t:'11:00–13:00',group:'11:00–16:00',cap:3},{k:'13-16',t:'13:00–16:00',group:'11:00–16:00',cap:3},{k:'16-19',t:'16:00–19:00',group:'16:00–21:00',cap:3},{k:'19-21',t:'19:00–21:00',group:'16:00–21:00',cap:3},{k:'21-00',t:'21:00–00:00',group:'21:00–02:00',cap:2},{k:'00-02',t:'00:00–02:00',group:'21:00–02:00',cap:2}];function scheduleFor(date,key){return db.schedule.filter(x=>x.work_date===date&&x.slot_key===key)}function renderMyStats(){let a=db.staff.find(x=>x.id===accountStaffId);if(!a){$('myStatsContent').innerHTML='<div class="empty">Ваш аккаунт ещё не привязан к сотруднику в составе. Обратитесь к Создателю.</div>';return}let x=metrics(a),days=[];for(let d=1;d<=dim();d++){let k=key(month.getFullYear(),month.getMonth(),d),m=mark(a.id,k);if(m.status!=='none')days.push('<div class="myStatDay"><b>'+new Date(k+'T12:00:00').toLocaleDateString('ru-RU',{day:'2-digit',month:'short'})+'</b><span class="'+(m.status==='inactive'?'bad':'')+'">'+(m.status==='inactive'?'Неактив':(+m.norm||0)+' ч')+'</span><small>'+esc(m.note||'Без комментария')+'</small></div>')} $('myStatsContent').innerHTML='<div class="myIdentity"><div><span class="eyebrow">СОТРУДНИК</span><h3>'+esc(a.name)+'</h3><small>'+esc(a.role)+' · назначен '+esc(a.appointed||'—')+'</small></div><div class="punishmentPills"><span>Ж/К <b>'+a.yellow+'</b></span><span>К/К <b>'+a.red+'</b></span></div></div><div class="myStatsGrid"><div><span>Выполнено нормы</span><b>'+x.ok+'</b></div><div><span>Неактивов</span><b>'+x.bad+'</b></div><div><span>Часов за месяц</span><b>'+x.norm+'</b></div><div><span>Средний онлайн</span><b>'+x.avg.toFixed(1)+' ч</b></div><div><span>Выполнение</span><b>'+x.pct+'%</b></div></div><div class="myHistoryHead"><h3>'+M[month.getMonth()]+' '+month.getFullYear()+'</h3><span>Только просмотр</span></div><div class="myStatDays">'+(days.join('')||'<div class="empty">Отметок за месяц пока нет.</div>')+'</div>'}
